{
  "root_causes": [
    {
      "service": "rate",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT min(time) t0, max(time) t1, count(*) n, avg(value) v FROM abnormal_metrics WHERE metric='k8s.deployment.available' AND attr_k8s_deployment_name='rate'",
          "claim": "rate deployment has 0 available replicas across all 18 abnormal samples, versus 1 in normal."
        },
        {
          "kind": "trace",
          "sql": "SELECT count(*) n FROM abnormal_traces WHERE service_name='rate'",
          "claim": "rate emitted zero spans during the abnormal window, versus about 585 server spans in normal."
        }
      ]
    },
    {
      "service": "search",
      "fault_kind": "application_exception",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, count(*) n, avg(CASE WHEN attr_status_code='Error' THEN 1.0 ELSE 0 END) err FROM abnormal_traces WHERE service_name='search' AND span_name='rate.Rate/GetRates' GROUP BY 1",
          "claim": "All 601 search calls to rate.Rate/GetRates returned Error, versus 0 errors in normal."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, message, count(*) n FROM abnormal_logs WHERE level='ERROR' GROUP BY ALL ORDER BY n DESC",
          "claim": "search logged 721 ERROR entries 'Failed to get rates from rate service'; frontend logged 710 'Search service failed'."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "rate",
      "to": "search",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT min(time) t0, max(time) t1, count(*) n, avg(CASE WHEN attr_status_code='Error' THEN 1.0 ELSE 0 END) err FROM abnormal_traces WHERE service_name='search' AND span_name='rate.Rate/GetRates'",
          "claim": "search's calls to rate start failing from 02:50:03 onward, with a 100% error share for the whole window."
        }
      ]
    },
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind k, count(*) n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='frontend' AND span_name IN ('search.Search/Nearby','HTTP /hotels') GROUP BY ALL",
          "claim": "Every frontend call to search.Search/Nearby and every HTTP /hotels server span returned Error, 613 of 613."
        }
      ]
    }
  ]
}
